24	@RestController
25	@CrossOrigin(exposedHeaders = "errors, content-type")
26	@RequestMapping("/api")
27	public class OwnerRestControllerV2 implements OwnerV2Api {
28	
29	    private final ClinicService clinicService;
30	    private final OwnerMapper ownerMapper;
31	
32	    public OwnerRestControllerV2(ClinicService clinicService, OwnerMapper ownerMapper) {
33	        this.clinicService = clinicService;
34	        this.ownerMapper = ownerMapper;
35	    }
36	
37	    @Override
38	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
39	    public ResponseEntity<OwnerPageDto> listOwnersPage(String lastName, Integer page, Integer size) {
40	        int pageNumber = page == null ? 0 : page;
41	        int pageSize = size == null ? 20 : size;
42	        Page<Owner> owners = this.clinicService.findOwners(
43	            lastName,
44	            PageRequest.of(pageNumber, pageSize, Sort.by("id")));
45	        OwnerPageDto pageDto = ownerMapper.toOwnerPageDto(owners);
46	        applyMembership(pageDto.getContent(), owners.getContent());
47	        return new ResponseEntity<>(pageDto, HttpStatus.OK);
48	    }
49	
50	    /**
51	     * Populates {@code membershipPoints} and {@code membershipLevel} on each dto in the page,
52	     * sizing every household from a single scan of all owners so the household-of-three-or-more
53	     * factor is scored correctly. The dtos and owners are in the same order.
54	     *
55	     * @param ownerDtos the page content to populate
56	     * @param owners    the owners the dtos were mapped from, in matching order
57	     */
58	    private void applyMembership(List<OwnerDto> ownerDtos, List<Owner> owners) {
59	        Map<String, Integer> householdSizes = new HashMap<>();
60	        for (Owner owner : this.clinicService.findAllOwners()) {
61	            if (owner.getHouseholdId() != null) {
62	                householdSizes.merge(owner.getHouseholdId(), 1, Integer::sum);
63	            }
64	        }
65	        for (int i = 0; i < ownerDtos.size() && i < owners.size(); i++) {
66	            Owner owner = owners.get(i);
67	            int householdSize = owner.getHouseholdId() == null ? 1
68	                : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
69	            int points = MembershipPoints.points(owner, householdSize);
70	            ownerDtos.get(i).setMembershipPoints(points);
71	            ownerDtos.get(i).setMembershipLevel(MembershipPoints.level(points));
72	        }
73	    }
74	}
