73	    /**
74	     * The header carrying an idempotency key for owner creation. When a create repeats with a key
75	     * already seen, the originally created owner is returned with 200 instead of creating a duplicate.
76	     */
77	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
78	
79	    /**
80	     * Remembers, per seen idempotency key, the id of the owner that create originally produced, so a
81	     * repeat of the same request returns that owner rather than creating a duplicate.
82	     */
83	    private final Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
