103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
106	        Collection<Owner> owners;
107	        if (lastName != null) {
108	            owners = this.clinicService.findOwnerByLastName(lastName);
109	        } else {
110	            owners = this.clinicService.findAllOwners();
111	        }
112	        if (owners.isEmpty()) {
113	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
114	        }
115	        Map<String, Integer> householdSizes = householdSizes();
116	        List<OwnerDto> ownerDtos = new java.util.ArrayList<>();
117	        for (Owner owner : owners) {
118	            OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
119	            applyMembership(ownerDto, owner, householdSizes);
120	            ownerDtos.add(ownerDto);
121	        }
122	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
123	    }
