128	        Owner owner = this.clinicService.findOwnerById(ownerId);
129	        if (owner == null) {
130	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
131	        }
132	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
133	        applyMembership(ownerDto, owner);
134	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
135	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
136	    }
