138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
141	        HttpHeaders headers = new HttpHeaders();
142	        String idempotencyKey = currentIdempotencyKey();
143	        if (idempotencyKey != null) {
144	            Integer existingId = idempotentCreates.get(idempotencyKey);
145	            if (existingId != null) {
146	                Owner existing = this.clinicService.findOwnerById(existingId);
147	                if (existing != null) {
148	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
149	                    applyMembership(existingDto, existing);
150	                    existingDto.setBulkSignupWarning(isBulkSignupDay());
151	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
152	                }
153	            }
154	        }
155	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
156	        String address = applyAddress(owner, ownerFieldsDto);
157	        if (address.isEmpty()) {
158	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
159	        }
160	        owner.setAddress(address);
161	        String telephone = toE164(owner.getTelephone());
162	        if (telephone == null) {
163	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
164	        }
165	        owner.setTelephone(telephone);
166	        if (owner.getEmail() != null) {
167	            String email = normalizeEmail(owner.getEmail());
168	            if (email == null) {
169	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
170	            }
171	            owner.setEmail(email);
172	        }
173	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
174	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
175	        }
176	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
177	        if (effectiveRegistrationDate == null) {
178	            effectiveRegistrationDate = LocalDate.now();
179	        }
180	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
181	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
182	        }
183	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
184	        owner.setRegistrationDate(registrationDate);
185	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
186	            return new ResponseEntity<>(HttpStatus.CONFLICT);
187	        }
188	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
189	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
190	        }
191	        // The householdId is deterministic: the first twelve hex characters of SHA-256 over
192	        // '<normalizedLastName>|<postcode>'. Owners sharing a last name and postcode therefore
193	        // share the household automatically. An owner without a postcode has no household.
194	        boolean declaredHouseholdMember = false;
195	        if (owner.getPostcode() != null) {
196	            String householdId = householdId(householdKey(owner.getLastName()), owner.getPostcode());
197	            owner.setHouseholdId(householdId);
198	            // Because the household is now keyed on (lastName, postcode), a second owner in the
199	            // same household is a household duplicate: rejected with 409 unless it opts in with
200	            // 'sharesHousehold', in which case it is created as a declared household member.
201	            boolean householdOccupied = false;
202	            for (Owner existing : this.clinicService.findAllOwners()) {
203	                if (existing.isDeleted()) {
204	                    continue;
205	                }
206	                if (householdId.equals(computeHouseholdId(existing))) {
207	                    householdOccupied = true;
208	                    break;
209	                }
210	            }
211	            if (householdOccupied) {
212	                if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
213	                    return new ResponseEntity<>(HttpStatus.CONFLICT);
214	                }
215	                declaredHouseholdMember = true;
216	            }
217	        }
218	        // Consolidated duplicate detection: reject only when the whole identityKey
219	        // (normalized telephone | email | householdId) matches an existing owner's.
220	        String identityKey = identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
221	        for (Owner existing : this.clinicService.findAllOwners()) {
222	            if (existing.isDeleted()) {
223	                continue;
224	            }
225	            if (identityKey.equals(identityKey(toE164(existing.getTelephone()),
226	                emailForKey(existing.getEmail()), existing.getHouseholdId()))) {
227	                return new ResponseEntity<>(HttpStatus.CONFLICT);
228	            }
229	        }
230	        // Soft-match: the owner is not a hard (identityKey) duplicate, but if it shares an
231	        // existing owner's last name and postcode while having a different normalized
232	        // telephone it is still created and flagged as a possible duplicate of that owner. A
233	        // declared household member, however, is not a suspected duplicate, so it is never flagged.
234	        if (declaredHouseholdMember) {
235	            owner.setPossibleDuplicate(false);
236	        }
237	        else {
238	            applyPossibleDuplicate(owner);
239	        }
240	        owner.setCustomerCode(deduplicatedCustomerCode(
241	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
242	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
243	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
244	        this.clinicService.saveOwner(owner);
245	        if (idempotencyKey != null) {
246	            idempotentCreates.put(idempotencyKey, owner.getId());
247	        }
248	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
249	        applyMembership(ownerDto, owner);
250	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
251	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
252	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
253	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
254	        headers.setLocation(UriComponentsBuilder.newInstance()
255	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
256	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
257	    }
258	
259	    /**
260	     * Reads the {@code Idempotency-Key} header of the request currently being handled, used to make
261	     * owner creation idempotent. Returns the trimmed key when present and non-blank, otherwise
262	     * {@code null} (including when there is no active servlet request), so a missing or blank key
263	     * simply means "no idempotency" and the create proceeds normally.
264	     *
265	     * @return the current request's idempotency key, or {@code null} when none is supplied
266	     */
267	    private static String currentIdempotencyKey() {
268	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
269	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
270	            return null;
271	        }
272	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
273	        if (key == null || key.isBlank()) {
274	            return null;
275	        }
276	        return key.trim();
277	    }
