279	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
280	    @Override
281	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
282	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
283	        if (currentOwner == null) {
284	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
285	        }
286	        currentOwner.setAddress(ownerFieldsDto.getAddress());
287	        currentOwner.setCity(ownerFieldsDto.getCity());
288	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
289	        currentOwner.setLastName(ownerFieldsDto.getLastName());
290	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
291	        this.clinicService.saveOwner(currentOwner);
292	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
293	    }
