295	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
296	    @Transactional
297	    @Override
298	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
299	        Owner owner = this.clinicService.findOwnerById(ownerId);
300	        if (owner == null) {
301	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
302	        }
303	        // Soft delete: the row is retained and flagged deleted rather than removed, so the
304	        // owner is still readable via GET but is ignored by the create duplicate/identity checks.
305	        owner.setDeleted(true);
306	        this.clinicService.saveOwner(owner);
307	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
308	    }
