375	    /**
376	     * The maximum number of owners permitted per city. Owner creation is rejected once the
377	     * owner's city already contains this many owners.
378	     */
379	    private static final int MAX_OWNERS_PER_CITY = 50;
380	
381	    /**
382	     * Counts how many existing owners live in the given city, compared case-insensitively.
383	     * This is evaluated before the new owner is persisted, so the owner being created is not
384	     * included in the count.
385	     *
386	     * @param city the new owner's city
387	     * @return the number of existing owners in that city
388	     */
389	    private int countOwnersInCity(String city) {
390	        int count = 0;
391	        for (Owner existing : this.clinicService.findAllOwners()) {
392	            if (city.equalsIgnoreCase(existing.getCity())) {
393	                count++;
394	            }
395	        }
396	        return count;
397	    }
398	
399	    /**
400	     * The maximum number of owners that may be created in a single business day. Owner
401	     * creation is rejected once this many owners already fall on the new owner's adjusted
402	     * business day {@code registrationDate}.
403	     */
404	    private static final int MAX_OWNERS_PER_DAY = 100;
405	
406	    /**
407	     * The fixed list of public holidays that the business-day roll skips over. A date that
408	     * lands on one of these is rolled forward to the next non-holiday business day.
409	     */
410	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
411	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
412	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
413	        LocalDate.parse("2026-12-28"));
414	
415	    /**
416	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
417	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
418	     * while a date that is already a non-holiday weekday is returned unchanged.
419	     *
420	     * @param date the date to adjust
421	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
422	     */
423	    private LocalDate toBusinessDay(LocalDate date) {
424	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
425	                || PUBLIC_HOLIDAYS.contains(date)) {
426	            date = date.plusDays(1);
427	        }
428	        return date;
429	    }
430	
431	    /**
432	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
433	     * registrationDate} rolls forward to the same business day. This is evaluated before the
434	     * new owner is persisted, so the owner being created is not included in the count.
435	     *
436	     * @param businessDay the adjusted business day to count against
437	     * @return the number of existing owners registered on that business day
438	     */
439	    private int countOwnersRegisteredOn(LocalDate businessDay) {
440	        int count = 0;
441	        for (Owner existing : this.clinicService.findAllOwners()) {
442	            LocalDate existingDate = existing.getRegistrationDate();
443	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
444	                count++;
445	            }
446	        }
447	        return count;
448	    }
449	
450	    /**
451	     * The number of owners that may be created on a single business day before a bulk-signup
452	     * warning is raised. Once more than this many owners already fall on the current business
453	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
454	     */
455	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
456	
457	    /**
458	     * Reports whether an unusually high number of owners have been created for today's business
459	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
460	     * the business day that {@code LocalDate.now()} rolls forward to.
461	     *
462	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
463	     */
464	    private boolean isBulkSignupDay() {
465	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
466	    }
