468	    /**
469	     * Builds the customer code for a newly created owner, formatted
470	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
471	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
472	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
473	     * first eight upper-case hex characters of the SHA-256 digest of
474	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
475	     * stable for a given telephone and last name rather than dependent on creation order.
476	     *
477	     * @param postcode            the owner's postcode (may be {@code null})
478	     * @param normalizedTelephone the owner's normalized E.164 telephone
479	     * @param lastName            the owner's last name
480	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
481	     */
482	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
483	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
484	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
485	    }
486	
487	    /**
488	     * De-duplicates a freshly computed {@code base} customer code against the codes already
489	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
490	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
491	     * yields a code no existing owner holds.
492	     *
493	     * @param base the computed {@code '<REGION>-<HASH8>'} customer code
494	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
495	     */
496	    private String deduplicatedCustomerCode(String base) {
497	        Set<String> existing = new HashSet<>();
498	        for (Owner owner : this.clinicService.findAllOwners()) {
499	            if (owner.getCustomerCode() != null) {
500	                existing.add(owner.getCustomerCode());
501	            }
502	        }
503	        if (!existing.contains(base)) {
504	            return base;
505	        }
506	        int n = 2;
507	        while (existing.contains(base + "-" + n)) {
508	            n++;
509	        }
510	        return base + "-" + n;
511	    }
512	
513	    /**
514	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
515	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
516	     *
517	     * @param source the string to hash
518	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
519	     */
520	    private static String sha256Hex8(String source) {
521	        try {
522	            byte[] digest = MessageDigest.getInstance("SHA-256")
523	                .digest(source.getBytes(StandardCharsets.UTF_8));
524	            StringBuilder hex = new StringBuilder(digest.length * 2);
525	            for (byte b : digest) {
526	                hex.append(String.format("%02x", b));
527	            }
528	            return hex.substring(0, 8).toUpperCase();
529	        } catch (NoSuchAlgorithmException e) {
530	            throw new IllegalStateException("SHA-256 not available", e);
531	        }
532	    }
533	
534	    /**
535	     * Builds the membership number for a newly created owner, formatted
536	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
537	     * customer code and {@code YY} is the last two digits of the fiscal year of the owner's
538	     * business-day-adjusted registration date, zero-padded to two digits. The fiscal year
539	     * starts on 1 July and is named by the calendar year it ends in.
540	     *
541	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
542	     * @param registrationDate the owner's business-day-adjusted registration date
543	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M27'})
544	     */
545	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
546	        int fiscalYear = org.springframework.samples.petclinic.mapper.FiscalYear.yearValue(registrationDate);
547	        return String.format("%s-M%02d", customerCode, Math.floorMod(fiscalYear, 100));
548	    }
