551	     * Counts how many existing owners share the given first and last name, compared
552	     * case-insensitively. This is evaluated before the new owner is persisted, so the
553	     * owner being created is not included in the count.
554	     *
555	     * @param firstName the new owner's first name
556	     * @param lastName  the new owner's last name
557	     * @return the number of existing owners with the same first and last name
558	     */
559	    private int countNamesakes(String firstName, String lastName) {
560	        int count = 0;
561	        for (Owner existing : this.clinicService.findAllOwners()) {
562	            if (firstName.equalsIgnoreCase(existing.getFirstName())
563	                && lastName.equalsIgnoreCase(existing.getLastName())) {
564	                count++;
565	            }
566	        }
