570	    /**
571	     * Canonical expansions applied to common street-type abbreviations during address
572	     * normalization. Keys and values are upper-cased so the lookup runs after the address
573	     * has itself been upper-cased.
574	     */
575	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
576	        "ST", "STREET",
577	        "RD", "ROAD",
578	        "AVE", "AVENUE");
579	
580	    /**
581	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
582	     * every run of internal whitespace is collapsed to a single space, the result is
583	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
584	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
585	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
586	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
587	     * returned and compared for household duplicates; an address that is blank once
588	     * normalized fails the required-field check.
589	     *
590	     * @param address the raw address value supplied by the client
591	     * @return the normalized address (empty string when {@code address} is null or blank)
592	     */
593	    /**
594	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
595	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
596	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
597	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
598	     * address returned is the normalized {@code addressLine1} with a single space and the
599	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
600	     * the flat {@code address} is normalized and returned, and the structured lines are left
601	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
602	     * downstream (household hash, postcode validation and locality); an owner that supplies
603	     * neither form yields an empty string, failing the required-address check.
604	     *
605	     * @param owner          the owner being created, whose structured address lines are set here
606	     * @param ownerFieldsDto the submitted owner fields
607	     * @return the composed, normalized address (empty string when no address form is supplied)
608	     */
609	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
610	        String addressLine1 = ownerFieldsDto.getAddressLine1();
611	        if (addressLine1 != null && !addressLine1.isBlank()) {
612	            String normalizedLine1 = normalizeAddress(addressLine1);
613	            owner.setAddressLine1(normalizedLine1);
614	            String addressLine2 = ownerFieldsDto.getAddressLine2();
615	            if (addressLine2 != null && !addressLine2.isBlank()) {
616	                String normalizedLine2 = normalizeAddress(addressLine2);
617	                owner.setAddressLine2(normalizedLine2);
618	                return normalizedLine1 + " " + normalizedLine2;
619	            }
620	            owner.setAddressLine2(null);
621	            return normalizedLine1;
622	        }
623	        owner.setAddressLine1(null);
624	        owner.setAddressLine2(null);
625	        return normalizeAddress(ownerFieldsDto.getAddress());
626	    }
627	
628	    private static String normalizeAddress(String address) {
629	        if (address == null) {
630	            return "";
631	        }
632	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
633	        if (collapsed.isEmpty()) {
634	            return "";
635	        }
636	        StringBuilder normalized = new StringBuilder(collapsed.length());
637	        for (String token : collapsed.split(" ")) {
638	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
639	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
640	            if (normalized.length() > 0) {
641	                normalized.append(' ');
642	            }
643	            normalized.append(expanded != null ? expanded : token);
644	        }
645	        return normalized.toString();
646	    }
