648	    /**
649	     * Normalizes a last name or address for household-duplicate comparison: leading and
650	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
651	     * single space and the result is lower-cased. Two owners are considered to share a
652	     * household when both their last names and addresses produce the same key.
653	     *
654	     * @param value the raw last name or address value
655	     * @return the normalized comparison key (empty string when {@code value} is null)
656	     */
657	    private static String householdKey(String value) {
658	        if (value == null) {
659	            return "";
660	        }
661	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
662	    }
663	
664	    /**
665	     * Derives the stable shared household identifier for the given normalized last name key
666	     * and postcode. The identifier is deterministic — the same household (same
667	     * {@link #householdKey normalized} last name and postcode) always maps to the same
668	     * value — so every owner in a household is assigned an identical id. It is the
669	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
670	     * '<lastNameKey>|<postcode>'}.
671	     *
672	     * @param lastNameKey the normalized last name key
673	     * @param postcode    the owner's postcode
674	     * @return the shared household identifier
675	     */
676	    private static String householdId(String lastNameKey, String postcode) {
677	        String source = lastNameKey + "|" + postcode;
678	        try {
679	            byte[] digest = MessageDigest.getInstance("SHA-256")
680	                .digest(source.getBytes(StandardCharsets.UTF_8));
681	            StringBuilder hex = new StringBuilder(digest.length * 2);
682	            for (byte b : digest) {
683	                hex.append(String.format("%02x", b));
684	            }
685	            return hex.substring(0, 12).toUpperCase();
686	        } catch (NoSuchAlgorithmException e) {
687	            throw new IllegalStateException("SHA-256 not available", e);
688	        }
689	    }
690	
691	    /**
692	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
693	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
694	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
695	     * collides with a computed household id.
696	     *
697	     * @param owner the existing owner
698	     * @return the owner's household id, or {@code null} when it has no postcode
699	     */
700	    private static String computeHouseholdId(Owner owner) {
701	        if (owner.getPostcode() == null) {
702	            return null;
703	        }
704	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
705	    }
