707	    /**
708	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
709	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
710	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
711	     * when mapping a collection to size every household from a single scan.
712	     *
713	     * @param ownerDto the dto to populate
714	     * @param owner    the owner being mapped
715	     */
716	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
717	        applyMembership(ownerDto, owner, householdSizes());
718	    }
