736	    /**
737	     * Counts how many owners belong to each household, keyed by household id. Owners without a
738	     * household id (no postcode) are excluded — such an owner is its own single-member household.
739	     *
740	     * @return a map from household id to the number of owners sharing it
741	     */
742	    private Map<String, Integer> householdSizes() {
743	        Map<String, Integer> sizes = new java.util.HashMap<>();
744	        for (Owner existing : this.clinicService.findAllOwners()) {
745	            String householdId = existing.getHouseholdId();
746	            if (householdId != null) {
747	                sizes.merge(householdId, 1, Integer::sum);
748	            }
749	        }
750	        return sizes;
751	    }
