753	    /**
754	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
755	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
756	     * possible duplicate when an existing owner shares its last name (compared
757	     * case-insensitively with collapsed whitespace) and its postcode while having a
758	     * different normalized telephone; {@code possibleDuplicateOf} is then set to that
759	     * existing owner's id. When several existing owners match, the one with the lowest id
760	     * is chosen so the result is deterministic. When no such owner exists — or the new
761	     * owner has no postcode to compare — {@code possibleDuplicate} is set to {@code false}
762	     * and no matching id is recorded.
763	     *
764	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
765	     */
766	    private void applyPossibleDuplicate(Owner owner) {
767	        owner.setPossibleDuplicate(false);
768	        if (owner.getPostcode() == null) {
769	            return;
770	        }
771	        String lastNameKey = householdKey(owner.getLastName());
772	        Owner match = null;
773	        for (Owner existing : this.clinicService.findAllOwners()) {
774	            if (lastNameKey.equals(householdKey(existing.getLastName()))
775	                && owner.getPostcode().equals(existing.getPostcode())
776	                && !owner.getTelephone().equals(toE164(existing.getTelephone()))) {
777	                if (match == null || (existing.getId() != null
778	                    && existing.getId() < match.getId())) {
779	                    match = existing;
780	                }
781	            }
782	        }
783	        if (match != null) {
784	            owner.setPossibleDuplicate(true);
785	            owner.setPossibleDuplicateOf(match.getId());
786	        }
787	    }
