789	    /**
790	     * Builds the derived duplicate-detection identity key from an owner's normalized
791	     * telephone, email and household id, formatted {@code
792	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
793	     * duplicates only when their whole identity keys are equal; because the telephone is
794	     * part of the key, members of the same household with different telephones produce
795	     * different keys and are both allowed.
796	     *
797	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
798	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
799	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
800	     * @return the identity key string
801	     */
802	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
803	        return (normalizedTelephone == null ? "" : normalizedTelephone)
804	            + "|" + (email == null ? "" : email)
805	            + "|" + (householdId == null ? "" : householdId);
806	    }
