808	    /**
809	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
810	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
811	     * {@code null} when the owner has no email.
812	     *
813	     * @param email the existing owner's stored email (may be {@code null})
814	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
815	     */
816	    private static String emailForKey(String email) {
817	        return email == null ? null : email.trim().toLowerCase();
818	    }
