820	    /**
821	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
822	     * and brackets are stripped. When the number already carries a leading {@code '+'}
823	     * and country code these are kept; a number written in national trunk form (a leading
824	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
825	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
826	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
827	     * after the {@code '+'}, and its national-number length must be valid for the detected
828	     * country code (see {@link #hasValidNationalLength}).
829	     *
830	     * @param telephone the raw telephone value supplied by the client
831	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
832	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
833	     */
834	    private static String toE164(String telephone) {
835	        if (telephone == null) {
836	            return null;
837	        }
838	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
839	        String digits;
840	        if (cleaned.startsWith("+")) {
841	            digits = cleaned.substring(1);
842	        } else if (cleaned.startsWith("0")) {
843	            digits = "61" + cleaned.substring(1);
844	        } else {
845	            digits = "1" + cleaned;
846	        }
847	        if (!digits.matches("[0-9]{8,15}")) {
848	            return null;
849	        }
850	        if (!hasValidNationalLength(digits)) {
851	            return null;
852	        }
853	        return "+" + digits;
854	    }
855	
856	    /**
857	     * Validates the national-number length of an E.164 digit string against its country
858	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
859	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
860	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
861	     *
862	     * @param digits the E.164 digits (without the leading {@code '+'})
863	     * @return {@code true} when the national-number length is valid for the country code
864	     */
865	    private static boolean hasValidNationalLength(String digits) {
866	        if (digits.startsWith("61")) {
867	            return digits.length() - 2 == 9;
868	        }
869	        if (digits.startsWith("1")) {
870	            return digits.length() - 1 == 10;
871	        }
872	        return true;
873	    }
874	
875	    /**
876	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
877	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
878	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
879	     */
880	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
881	        "NSW", new int[] {2000, 2099},
882	        "VIC", new int[] {3000, 3099},
883	        "QLD", new int[] {4000, 4099});
884	
885	    /**
886	     * Validates an owner's postcode for creation. A postcode is only ever validated when
887	     * present (an absent postcode is optional and accepted). When present it must be exactly
888	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
889	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
890	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
891	     *
892	     * @param postcode the supplied postcode (never {@code null} here)
893	     * @param city     the owner's city, used to derive the region
894	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
895	     *         (signalling a 400 Bad Request)
896	     */
897	    private static boolean isValidPostcode(String postcode, String city) {
898	        if (!postcode.matches("[0-9]{4}")) {
899	            return false;
900	        }
901	        int[] range = REGION_POSTCODES.get(
902	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
903	        if (range == null) {
904	            return true;
905	        }
906	        int value = Integer.parseInt(postcode);
907	        return value >= range[0] && value <= range[1];
908	    }
909	
910	    /**
911	     * Disposable email domains that are not accepted for owner creation. An owner whose
912	     * email domain (compared case-insensitively) is in this set is rejected with a 400
913	     * Bad Request.
914	     */
915	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
916	        "mailinator.com", "tempmail.com", "guerrillamail.com");
917	
918	    /**
919	     * Normalizes an owner email for creation. A present email must be a syntactically
920	     * valid address whose domain is not on the disposable-domain blocklist ({@link
921	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
922	     *
923	     * @param email the raw email value supplied by the client (never {@code null} here)
924	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
925	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
926	     */
927	    private static String normalizeEmail(String email) {
928	        String trimmed = email.trim();
929	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
930	            return null;
931	        }
932	        String normalized = trimmed.toLowerCase();
933	        String domain = normalized.substring(normalized.indexOf('@') + 1);
934	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
935	            return null;
936	        }
937	        return normalized;
938	    }
