3	import java.time.LocalDate;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Computes an owner's {@code membershipPoints} and the {@code membershipLevel} derived from
9	 * them. Points start at 0 and accrue: plus 2 when an email is present, plus 1 when the owner's
10	 * namesakeCount is 0, plus 2 when the owner belongs to a household of three or more members,
11	 * and plus 3 when the owner's tenure (elapsed fiscal years since its registration date)
12	 * exceeds one fiscal year. The level maps the points as 1 (0-1), 2 (2-3), 3 (4-5) and
13	 * 4 (6 or more).
14	 *
15	 * <p>Kept out of {@link OwnerMapper} so MapStruct does not mistake it for an implicit mapping
16	 * method and apply it to every property.
17	 */
18	public final class MembershipPoints {
19	
20	    private MembershipPoints() {
21	    }
22	
23	    /**
24	     * Compute the owner's membership points.
25	     *
26	     * @param owner         the owner to score
27	     * @param householdSize the number of members in the owner's household (the owner counts as
28	     *                      one), used for the household-of-three-or-more factor
29	     * @return the total membership points (never negative)
30	     */
31	    public static int points(Owner owner, int householdSize) {
32	        int points = 0;
33	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
34	            points += 2;
35	        }
36	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
37	            points += 1;
38	        }
39	        if (householdSize >= 3) {
40	            points += 2;
41	        }
42	        if (owner.getRegistrationDate() != null
43	            && FiscalYear.elapsed(owner.getRegistrationDate(), LocalDate.now()) > 1) {
44	            points += 3;
45	        }
46	        return points;
47	    }
48	
49	    /**
50	     * Map membership points to a membership level: 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and
51	     * 4 for 6 or more.
52	     *
53	     * @param points the membership points
54	     * @return the membership level (1-4)
55	     */
56	    public static int level(int points) {
57	        if (points >= 6) {
58	            return 4;
59	        }
60	        if (points >= 4) {
61	            return 3;
62	        }
63	        if (points >= 2) {
64	            return 2;
65	        }
66	        return 1;
67	    }
68	}
